test('cobra el total y guarda el pedido pagado', async () => {
  // stub: la pasarela siempre aprueba
  const pasarela = { cobrar: jest.fn().mockResolvedValue({ estado: 'aprobado' }) };
  // spy sobre un repositorio en memoria (fake)
  const repo = new PedidoRepositorioEnMemoria();
  const guardar = jest.spyOn(repo, 'guardar');

  await new Checkout(pasarela, repo).pagar({ id: 7, total: 50 });

  expect(pasarela.cobrar).toHaveBeenCalledWith(50);          // mock: interacción
  expect(guardar).toHaveBeenCalledWith(expect.objectContaining({ estado: 'pagado' }));
});

